/**
 * Broadcast / announcements — an admin pushes a message; every customer sees it
 * as a dismissible banner in their portal. Admin actions are area-gated
 * ("platform", same as the other content tools); customer actions require a
 * signed-in user and only ever touch that user's own dismissal rows.
 */

const LEVELS = ["INFO", "SUCCESS", "WARNING", "CRITICAL"] as const;
export type AnnouncementLevel = (typeof LEVELS)[number];

export type AnnouncementView = {
  id: string;
  title: string;
  body: string | null;
  level: AnnouncementLevel;
};

// ---------- Admin ----------

export async function createAnnouncement(input: {
  title: string;
  body?: string;
  level?: string;
  startsAt?: string | null;
  expiresAt?: string | null;
}): Promise<{ error?: string; ok?: boolean }> {
  const admin = await requireArea("platform");
  const title = String(input.title ?? "").trim();
  if (!title) return { error: "Enter a title." };
  const level = LEVELS.includes(input.level as AnnouncementLevel) ? (input.level as AnnouncementLevel) : "INFO";
  const startsAt = input.startsAt ? new Date(input.startsAt) : null;
  if (startsAt && Number.isNaN(startsAt.getTime())) return { error: "Invalid start date." };
  const expiresAt = input.expiresAt ? new Date(input.expiresAt) : null;
  if (expiresAt && Number.isNaN(expiresAt.getTime())) return { error: "Invalid expiry date." };
  if (startsAt && expiresAt && expiresAt <= startsAt) return { error: "End must be after start." };
  await db.announcement.create({
    data: { title: title.slice(0, 200), body: (input.body ?? "").trim().slice(0, 2000) || null, level, startsAt, expiresAt, createdBy: admin.id },
  });
  revalidatePath("/admin/broadcast");
  return { ok: true };
}

export async function listAnnouncements() {
  await requireArea("platform");
  return db.announcement.findMany({
    orderBy: { createdAt: "desc" },
    take: 100,
    include: { _count: { select: { dismissals: true } } },
  });
}

export async function toggleAnnouncement(id: string): Promise<void> {
  await requireArea("platform");
  const a = await db.announcement.findUnique({ where: { id }, select: { active: true } });
  if (!a) return;
  await db.announcement.update({ where: { id }, data: { active: !a.active } });
  revalidatePath("/admin/broadcast");
}

export async function deleteAnnouncement(id: string): Promise<void> {
  await requireArea("platform");
  await db.announcement.delete({ where: { id } }).catch(() => undefined); // dismissals cascade
  revalidatePath("/admin/broadcast");
}

