"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import { requireArea } from "./rbac";

/**
 * Update Announcements — service-specific release notes pushed to customers.
 *
 * Admin creates a DRAFT, then explicitly publishes it (the approval gate).
 * Customers see a popup on first login after publish and a persistent
 * "What's New" feed. `serviceTypes` scopes visibility: a user only sees
 * announcements for services they actually have; empty = everyone.
 *
 * Admin actions are area-gated ("platform"). Customer actions self-auth via
 * `requireUser()` and only ever touch that user's own rows.
 */

const SERVICE_TYPES = ["GAME", "VPS", "HOSTING", "MAIL"] as const;
export type ServiceType = (typeof SERVICE_TYPES)[number];

// ---------- Admin ----------

export async function listAnnouncements() {
  await requireArea("platform");
  return db.updateAnnouncement.findMany({
    orderBy: { createdAt: "desc" },
    take: 200,
    include: { _count: { select: { seenBy: true } } },
  });
}

export async function createAnnouncement(input: {
  title: string;
  body: string;
  serviceTypes: string[];
  screenshotUrl?: string | null;
}): Promise<{ error?: string; ok?: boolean }> {
  await requireArea("platform");
  const title = String(input.title ?? "").trim();
  if (!title) return { error: "Enter a title." };
  const body = String(input.body ?? "").trim();
  if (!body) return { error: "Enter a body." };

  // Validate service types — only allow known values.
  const serviceTypes = (input.serviceTypes ?? []).filter((t) =>
    (SERVICE_TYPES as readonly string[]).includes(t),
  );

  // Screenshot must be a relative path, not an external URL.
  let screenshotUrl: string | null = null;
  if (input.screenshotUrl) {
    const u = input.screenshotUrl.trim();
    if (u && !u.startsWith("/")) return { error: "Screenshot must be a relative path (e.g. /uploads/announcements/img.png)." };
    screenshotUrl = u || null;
  }

  await db.updateAnnouncement.create({
    data: {
      title: title.slice(0, 200),
      body: body.slice(0, 10_000),
      serviceTypes,
      screenshotUrl,
      status: "DRAFT",
    },
  });
  revalidatePath("/admin/announcements");
  return { ok: true };
}

export async function publishAnnouncement(id: string): Promise<void> {
  await requireArea("platform");
  await db.updateAnnouncement.update({
    where: { id },
    data: { status: "PUBLISHED", publishedAt: new Date() },
  });
  revalidatePath("/admin/announcements");
}

export async function unpublishAnnouncement(id: string): Promise<void> {
  await requireArea("platform");
  await db.updateAnnouncement.update({
    where: { id },
    data: { status: "DRAFT" },
  });
  revalidatePath("/admin/announcements");
}

export async function deleteAnnouncement(id: string): Promise<void> {
  await requireArea("platform");
  await db.updateAnnouncement.delete({ where: { id } }).catch(() => undefined);
  revalidatePath("/admin/announcements");
}

// ---------- Customer ----------

/** Determine which service types the current user has active services for. */
async function getUserServiceTypes(userId: string): Promise<string[]> {
  const [servers, hosting] = await Promise.all([
    db.server.findFirst({ where: { userId } }),
    db.hostingAccount.findFirst({ where: { userId } }),
  ]);
  const types: string[] = [];
  if (servers) {
    const hasGame = await db.server.findFirst({
      where: { userId, gamePlanId: { not: null } },
    });
    if (hasGame) types.push("GAME");
    const hasVps = await db.server.findFirst({
      where: { userId, gamePlanId: null },
    });
    if (hasVps) types.push("VPS");
  }
  if (hosting) types.push("HOSTING");
  // MAIL: anyone with a hosting account potentially has mail; we keep it
  // simple and include MAIL for hosting customers too.
  if (hosting) types.push("MAIL");
  return types;
}

/**
 * PUBLISHED announcements the current user hasn't seen, filtered by service
 * types matching their actual services. An announcement with empty
 * serviceTypes[] is shown to everyone.
 */
export async function getUnseenAnnouncements() {
  const user = await requireUser();
  const userServices = await getUserServiceTypes(user.id);

  const announcements = await db.updateAnnouncement.findMany({
    where: {
      status: "PUBLISHED",
      seenBy: { none: { userId: user.id } },
    },
    orderBy: { publishedAt: "desc" },
  });

  // Filter by service type: show if announcement has no serviceTypes (global)
  // or if at least one of the user's service types matches.
  return announcements.filter(
    (a) =>
      a.serviceTypes.length === 0 ||
      a.serviceTypes.some((t) => userServices.includes(t)),
  );
}

/** Mark an announcement as seen by the current user. Upserts to stay idempotent. */
export async function markAnnouncementSeen(announcementId: string): Promise<void> {
  const user = await requireUser();
  await db.userAnnouncementSeen.upsert({
    where: {
      userId_announcementId: { userId: user.id, announcementId },
    },
    create: { userId: user.id, announcementId },
    update: {},
  });
}

export type WhatsNewEntry = {
  id: string;
  title: string;
  body: string;
  serviceTypes: string[];
  screenshotUrl: string | null;
  publishedAt: string; // ISO string for serialization
  seen: boolean;
};

/**
 * All PUBLISHED announcements, optionally filtered by service type, ordered
 * by publishedAt desc, with a `seen` boolean flag for the current user.
 */
export async function getWhatsNew(
  serviceFilter?: string,
): Promise<WhatsNewEntry[]> {
  const user = await requireUser();

  const where: Record<string, unknown> = { status: "PUBLISHED" };
  if (serviceFilter && (SERVICE_TYPES as readonly string[]).includes(serviceFilter)) {
    where.serviceTypes = { has: serviceFilter };
  }

  const announcements = await db.updateAnnouncement.findMany({
    where,
    orderBy: { publishedAt: "desc" },
    include: {
      seenBy: {
        where: { userId: user.id },
        take: 1,
      },
    },
  });

  return announcements.map((a) => ({
    id: a.id,
    title: a.title,
    body: a.body,
    serviceTypes: a.serviceTypes,
    screenshotUrl: a.screenshotUrl,
    publishedAt: (a.publishedAt ?? a.createdAt).toISOString(),
    seen: a.seenBy.length > 0,
  }));
}

import { requireArea } from "@/lib/rbac";
import { PageHeader } from "@/components/ui/primitives";
import { listAnnouncements } from "@/lib/actions-announcements";
import { AnnouncementsAdmin } from "@/components/admin/AnnouncementsAdmin";

export const dynamic = "force-dynamic";

export default async function AdminAnnouncementsPage() {
  await requireArea("platform");
  const rows = await listAnnouncements();
  return (
    <div className="space-y-6">
      <PageHeader
        title="Update Announcements"
        sub="Write release notes and service updates. Drafts are private; published announcements appear to customers as a popup and in their What's New feed."
      />
      <AnnouncementsAdmin
        rows={rows.map((r) => ({
          id: r.id,
          title: r.title,
          body: r.body,
          serviceTypes: r.serviceTypes,
          screenshotUrl: r.screenshotUrl,
          status: r.status,
          publishedAt: r.publishedAt ? r.publishedAt.toISOString() : null,
          createdAt: r.createdAt.toISOString(),
          seenCount: r._count.seenBy,
        }))}
      />
    </div>
  );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import {
  createAnnouncement,
  publishAnnouncement,
  unpublishAnnouncement,
  deleteAnnouncement,
} from "@/lib/actions-announcements";
import { renderMarkdown } from "@/lib/blog";

type Row = {
  id: string;
  title: string;
  body: string;
  serviceTypes: string[];
  screenshotUrl: string | null;
  status: string;
  publishedAt: string | null;
  createdAt: string;
  seenCount: number;
};

const SERVICE_OPTIONS = [
  { value: "GAME", label: "Game Servers" },
  { value: "VPS", label: "VPS" },
  { value: "HOSTING", label: "Hosting" },
  { value: "MAIL", label: "Mail" },
];

const STATUS_DOT: Record<string, string> = {
  DRAFT: "bg-amber-400",
  PUBLISHED: "bg-emerald-400",
};

const STATUS_BADGE: Record<string, string> = {
  DRAFT: "border-amber-500/40 bg-amber-500/10 text-amber-300",
  PUBLISHED: "border-emerald-500/40 bg-emerald-500/10 text-emerald-300",
};

export function AnnouncementsAdmin({ rows }: { rows: Row[] }) {
  const router = useRouter();
  const [title, setTitle] = useState("");
  const [body, setBody] = useState("");
  const [serviceTypes, setServiceTypes] = useState<string[]>([]);
  const [screenshotUrl, setScreenshotUrl] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState("");
  const [showPreview, setShowPreview] = useState(false);

  function toggleService(val: string) {
    setServiceTypes((prev) =>
      prev.includes(val) ? prev.filter((v) => v !== val) : [...prev, val],
    );
  }

  async function submit() {
    setErr("");
    setBusy(true);
    const res = await createAnnouncement({
      title,
      body,
      serviceTypes,
      screenshotUrl: screenshotUrl || null,
    });
    setBusy(false);
    if (res.error) {
      setErr(res.error);
      return;
    }
    setTitle("");
    setBody("");
    setServiceTypes([]);
    setScreenshotUrl("");
    setShowPreview(false);
    router.refresh();
  }

  async function doPublish(id: string) {
    await publishAnnouncement(id);
    router.refresh();
  }

  async function doUnpublish(id: string) {
    await unpublishAnnouncement(id);
    router.refresh();
  }

  async function doDelete(id: string) {
    if (!confirm("Delete this announcement permanently?")) return;
    await deleteAnnouncement(id);
    router.refresh();
  }

  return (
    <div className="space-y-6">
      {/* Create form */}
      <div className="card space-y-4">
        <p className="text-sm font-semibold text-white">New announcement</p>

        <input
          className="input"
          placeholder="Title (e.g. New backup system, Game server mods)"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          maxLength={200}
        />

        <textarea
          className="input font-mono text-sm"
          rows={6}
          placeholder="Body (Markdown supported: **bold**, ## headings, - lists, [links](url))"
          value={body}
          onChange={(e) => setBody(e.target.value)}
          maxLength={10000}
        />

        <div className="flex flex-wrap items-center gap-4">
          <span className="text-xs font-medium text-slate-400">
            Service types (empty = shown to all):
          </span>
          {SERVICE_OPTIONS.map((opt) => (
            <label
              key={opt.value}
              className="flex items-center gap-1.5 text-sm text-slate-300"
            >
              <input
                type="checkbox"
                checked={serviceTypes.includes(opt.value)}
                onChange={() => toggleService(opt.value)}
                className="accent-brand-500"
              />
              {opt.label}
            </label>
          ))}
        </div>

        <input
          className="input text-sm"
          placeholder="Screenshot path (optional, e.g. /uploads/announcements/screenshot.png)"
          value={screenshotUrl}
          onChange={(e) => setScreenshotUrl(e.target.value)}
        />

        <div className="flex items-center gap-3">
          <button
            className="btn-primary"
            onClick={submit}
            disabled={busy || !title.trim() || !body.trim()}
          >
            {busy ? "Creating..." : "Create draft"}
          </button>
          <button
            type="button"
            className="text-xs text-slate-400 hover:text-white"
            onClick={() => setShowPreview((p) => !p)}
          >
            {showPreview ? "Hide preview" : "Preview"}
          </button>
        </div>

        {err && <p className="text-sm text-red-400">{err}</p>}

        {/* Preview */}
        {showPreview && body.trim() && (
          <div className="rounded-xl border border-white/[0.06] bg-black/20 p-5">
            <p className="mb-3 text-xs font-medium uppercase tracking-wider text-slate-500">
              Preview
            </p>
            <h3 className="mb-2 text-lg font-bold text-white">
              {title || "Untitled"}
            </h3>
            <div
              className="prose-sm"
              dangerouslySetInnerHTML={{ __html: renderMarkdown(body) }}
            />
            {screenshotUrl && (
              <div className="mt-4">
                {/* eslint-disable-next-line @next/next/no-img-element */}
                <img
                  src={screenshotUrl}
                  alt="Screenshot preview"
                  className="w-full max-w-lg rounded-xl border border-white/10"
                />
              </div>
            )}
          </div>
        )}
      </div>

      {/* Announcements list */}
      <div className="card p-0">
        <div className="border-b border-white/[0.06] px-4 py-3 text-sm font-semibold text-white">
          All announcements ({rows.length})
        </div>
        {rows.length === 0 ? (
          <p className="px-4 py-6 text-sm text-slate-400">
            No announcements yet — use the form above to create your first one.
          </p>
        ) : (
          <ul className="divide-y divide-white/[0.06]">
            {rows.map((r) => (
              <li
                key={r.id}
                className="flex items-start justify-between gap-3 px-4 py-4"
              >
                <div className="min-w-0 flex-1">
                  <p className="flex items-center gap-2 text-sm font-medium text-slate-100">
                    <span
                      className={`h-2 w-2 shrink-0 rounded-full ${STATUS_DOT[r.status] ?? STATUS_DOT.DRAFT}`}
                    />
                    <span className="truncate">{r.title}</span>
                    <span
                      className={`inline-flex shrink-0 items-center rounded-full border px-2 py-0.5 text-[10px] font-medium ${STATUS_BADGE[r.status] ?? STATUS_BADGE.DRAFT}`}
                    >
                      {r.status.toLowerCase()}
                    </span>
                  </p>
                  {r.serviceTypes.length > 0 && (
                    <p className="mt-1 flex gap-1.5">
                      {r.serviceTypes.map((t) => (
                        <span
                          key={t}
                          className="rounded border border-white/10 bg-white/[0.05] px-1.5 py-0.5 text-[10px] text-slate-400"
                        >
                          {t}
                        </span>
                      ))}
                    </p>
                  )}
                  <p className="mt-1 line-clamp-2 text-xs text-slate-500">
                    {r.body}
                  </p>
                  <p className="mt-1 text-[11px] text-slate-500">
                    Created {new Date(r.createdAt).toLocaleDateString()}
                    {r.publishedAt &&
                      ` · Published ${new Date(r.publishedAt).toLocaleDateString()}`}
                    {" · "}Seen by {r.seenCount}
                  </p>
                </div>
                <div className="flex shrink-0 gap-3 text-xs">
                  {r.status === "DRAFT" ? (
                    <button
                      className="text-emerald-400 hover:underline"
                      onClick={() => doPublish(r.id)}
                    >
                      Publish
                    </button>
                  ) : (
                    <button
                      className="text-amber-400 hover:underline"
                      onClick={() => doUnpublish(r.id)}
                    >
                      Unpublish
                    </button>
                  )}
                  <button
                    className="text-red-400 hover:underline"
                    onClick={() => doDelete(r.id)}
                  >
                    Delete
                  </button>
                </div>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState, useTransition, useCallback } from "react";
import { createPortal } from "react-dom";
import {
  getUnseenAnnouncements,
  markAnnouncementSeen,
} from "@/lib/actions-announcements";
import { renderMarkdown } from "@/lib/blog";

type Announcement = {
  id: string;
  title: string;
  body: string;
  screenshotUrl: string | null;
  serviceTypes: string[];
  publishedAt: Date | null;
};

/**
 * Shows unseen update announcements as a modal popup, one at a time.
 * Mounted inside the dashboard layout so it only fires for authenticated users.
 * Uses createPortal to escape any transformed ancestors (same fix as
 * HeardAboutUsPrompt.tsx).
 */
export function AnnouncementPopup() {
  const [queue, setQueue] = useState<Announcement[]>([]);
  const [loaded, setLoaded] = useState(false);
  const [, startTransition] = useTransition();

  useEffect(() => {
    let cancelled = false;
    getUnseenAnnouncements()
      .then((items) => {
        if (!cancelled) {
          setQueue(items);
          setLoaded(true);
        }
      })
      .catch(() => {
        // Soft-fail: never block the portal over a failed announcement fetch.
        if (!cancelled) setLoaded(true);
      });
    return () => {
      cancelled = true;
    };
  }, []);

  const dismiss = useCallback(() => {
    const current = queue[0];
    if (!current) return;
    // Remove from queue optimistically.
    setQueue((prev) => prev.slice(1));
    // Persist the seen record in the background.
    startTransition(async () => {
      try {
        await markAnnouncementSeen(current.id);
      } catch {
        /* best-effort */
      }
    });
  }, [queue]);

  // Nothing to show (not loaded, or no unseen announcements).
  if (!loaded || queue.length === 0) return null;
  if (typeof document === "undefined") return null;

  const current = queue[0];

  return createPortal(
    <div
      className="fixed inset-0 z-[70] flex items-center justify-center bg-black/70 p-4 backdrop-blur-sm"
      role="dialog"
      aria-modal="true"
      aria-labelledby="announcement-title"
      onClick={dismiss}
    >
      <div
        className="card w-full max-w-lg overflow-hidden motion-safe:animate-panel-in"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div className="border-b border-white/[0.06] bg-gradient-to-r from-brand-500/10 to-accent-blue/10 px-6 py-4">
          <div className="flex items-center gap-2">
            <span className="flex h-6 w-6 items-center justify-center rounded-full bg-brand-500/20 text-brand-300">
              <svg
                width="14"
                height="14"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
              >
                <path d="M11 3l1.8 4.9L17.7 9.7l-4.9 1.8L11 16.4l-1.8-4.9L4.3 9.7l4.9-1.8zM18 14.5l.85 2.15L21 17.5l-2.15.85L18 20.5l-.85-2.15L15 17.5l2.15-.85z" />
              </svg>
            </span>
            <span className="text-xs font-medium uppercase tracking-wider text-brand-300">
              What&apos;s new
            </span>
          </div>
