    document.body,
  );
}

"use client";

import { useEffect, useState, useTransition, useRef, useCallback } from "react";
import {
  getWhatsNew,
  markAnnouncementSeen,
  type WhatsNewEntry,
} from "@/lib/actions-announcements";
import { renderMarkdown } from "@/lib/blog";

const FILTERS = [
  { value: "", label: "All" },
  { value: "GAME", label: "Game Servers" },
  { value: "VPS", label: "VPS" },
  { value: "HOSTING", label: "Hosting" },
  { value: "MAIL", label: "Mail" },
];

/**
 * Full "What's New" feed: all published announcements in a timeline layout.
 * Unseen ones get a "New" badge. When an unseen announcement scrolls into
 * view (or is present on initial render), it is marked as seen after a short
 * delay so the badge lingers long enough to be noticed.
 */
export function WhatsNew() {
  const [entries, setEntries] = useState<WhatsNewEntry[]>([]);
  const [filter, setFilter] = useState("");
  const [loading, setLoading] = useState(true);
  const [, startTransition] = useTransition();

  const load = useCallback((serviceFilter: string) => {
    setLoading(true);
    getWhatsNew(serviceFilter || undefined)
      .then(setEntries)
      .catch(() => setEntries([]))
      .finally(() => setLoading(false));
  }, []);

  useEffect(() => {
    load(filter);
  }, [filter, load]);

  function handleFilterChange(val: string) {
    setFilter(val);
  }

  /** Mark an announcement as seen (optimistic local update + server write). */
  function handleSeen(id: string) {
    setEntries((prev) =>
      prev.map((e) => (e.id === id ? { ...e, seen: true } : e)),
    );
    startTransition(async () => {
      try {
        await markAnnouncementSeen(id);
      } catch {
        /* best-effort */
      }
    });
  }

  return (
    <div className="space-y-6">
      {/* Filter tabs */}
      <div className="flex flex-wrap gap-2">
        {FILTERS.map((f) => (
          <button
            key={f.value}
            onClick={() => handleFilterChange(f.value)}
            className={`rounded-lg border px-3 py-1.5 text-sm font-medium transition-colors ${
              filter === f.value
                ? "border-brand-400/60 bg-brand-500/15 text-brand-200"
                : "border-white/10 bg-white/[0.03] text-slate-400 hover:border-white/20 hover:text-slate-200"
            }`}
          >
            {f.label}
          </button>
        ))}
      </div>

      {/* Content */}
      {loading ? (
        <div className="py-12 text-center text-sm text-slate-500">
          Loading...
        </div>
      ) : entries.length === 0 ? (
        <div className="card flex flex-col items-center justify-center py-14 text-center">
          <div className="mb-4 rounded-2xl border border-white/[0.08] bg-gradient-to-br from-accent-blue/15 to-brand-500/15 p-4">
            <svg
              width="28"
              height="28"
              viewBox="0 0 24 24"
              fill="none"
              stroke="#8a70fb"
              strokeWidth="1.5"
            >
              <path d="M11 3l1.8 4.9L17.7 9.7l-4.9 1.8L11 16.4l-1.8-4.9L4.3 9.7l4.9-1.8zM18 14.5l.85 2.15L21 17.5l-2.15.85L18 20.5l-.85-2.15L15 17.5l2.15-.85z" />
            </svg>
          </div>
          <p className="text-sm font-medium text-white">No updates yet</p>
          <p className="mt-1 text-sm text-slate-400">
            We&apos;ll post here when there&apos;s something new.
          </p>
        </div>
      ) : (
        <div className="space-y-4">
          {entries.map((entry) => (
            <AnnouncementCard
              key={entry.id}
              entry={entry}
              onSeen={handleSeen}
            />
          ))}
        </div>
      )}
    </div>
  );
}

function AnnouncementCard({
  entry,
  onSeen,
}: {
  entry: WhatsNewEntry;
  onSeen: (id: string) => void;
}) {
  const ref = useRef<HTMLDivElement>(null);
  const markedRef = useRef(false);

  useEffect(() => {
    if (entry.seen || markedRef.current) return;
    const el = ref.current;
    if (!el) return;

    const observer = new IntersectionObserver(
      ([e]) => {
        if (e.isIntersecting && !markedRef.current) {
          markedRef.current = true;
          // Short delay so the "New" badge is visible before it disappears.
          const timer = setTimeout(() => onSeen(entry.id), 2000);
          observer.disconnect();
          return () => clearTimeout(timer);
        }
      },
      { threshold: 0.5 },
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, [entry.id, entry.seen, onSeen]);

  const date = new Date(entry.publishedAt);
  const formatted = date.toLocaleDateString("en-US", {
    year: "numeric",
    month: "long",
    day: "numeric",
  });

  return (
    <div
      ref={ref}
      className="card relative overflow-hidden border border-white/[0.06]"
    >
      {/* Timeline dot + date row */}
      <div className="flex items-center gap-3 px-5 pt-5">
        <span className="h-2.5 w-2.5 shrink-0 rounded-full bg-brand-500" />
        <span className="text-xs text-slate-500">{formatted}</span>
        {!entry.seen && (
          <span className="inline-flex items-center rounded-full border border-brand-400/40 bg-brand-500/15 px-2 py-0.5 text-[10px] font-semibold text-brand-300">
            New
          </span>
        )}
        {entry.serviceTypes.length > 0 && (
          <div className="ml-auto flex gap-1.5">
            {entry.serviceTypes.map((t) => (
              <span
                key={t}
                className="rounded border border-white/10 bg-white/[0.05] px-1.5 py-0.5 text-[10px] text-slate-400"
              >
                {t}
              </span>
            ))}
          </div>
        )}
      </div>

      {/* Title */}
      <h3 className="mt-3 px-5 text-base font-bold text-white">
        {entry.title}
      </h3>

      {/* Body */}
      <div className="mt-2 px-5 pb-5">
        <div dangerouslySetInnerHTML={{ __html: renderMarkdown(entry.body) }} />
        {entry.screenshotUrl && (
          <div className="mt-4">
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img
              src={entry.screenshotUrl}
              alt={`Screenshot for ${entry.title}`}
              className="w-full rounded-xl border border-white/10 shadow-lg shadow-black/20"
              loading="lazy"
            />
          </div>
        )}
      </div>
    </div>
  );
}

import { WhatsNew } from "@/components/customer/WhatsNew";

export const dynamic = "force-dynamic";

export default function WhatsNewPage() {
  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-bold tracking-tight text-white">
          What&apos;s New
        </h1>
        <p className="mt-1 text-sm text-slate-400">
          Updates, improvements, and new features across all Nxeon services.
        </p>
      </div>
      <WhatsNew />
    </div>
  );
}

